solution:
fn sign(x: Int) -> Int
  ensures: result == -1 || result == 0 || result == 1;
  ensures: result * x >= 0;
{
  if x < 0 { return -1; }
  if x > 0 { return 1; }
  return 0;
}

fn main() -> Int {
  return sign(-42);
}
